MANUAL = json.loads(r'''{"V2-Q0832":{"stem":"A client develops sudden severe unilateral pelvic pain with nausea and vomiting. Which condition requires urgent evaluation?","key":"D","options":{"A":"Musculoskeletal strain, which more often follows exertion and lacks the typical pattern of an acute adnexal emergency.","B":"Primary dysmenorrhea, which usually follows a cyclic menstrual pattern rather than abrupt focal severe pain.","C":"Lower urinary infection, which more often causes urinary symptoms than abrupt, severe, one-sided pelvic pain.","D":"Ovarian torsion, which can cause sudden unilateral pelvic pain with nausea and needs urgent clinical evaluation."},"authority":"P","source_name":"ACOG — Adnexal Torsion in Adolescents","source_url":"https://www.acog.org/clinical/clinical-guidance/committee-opinion/articles/2019/08/adnexal-torsion-in-adolescents","source_locator":"Committee Opinion No. 783, Recommendations and Evaluation sections: sudden-onset intermittent abdominal pain with nausea/vomiting; timely diagnostic laparoscopy when torsion is suspected.","source_version":"ACOG Committee Opinion 783, August 2019; live ACOG clinical guidance rechecked 2026-08-15.","finding":"Ovarian/adnexal torsion commonly presents with sudden abdominal or pelvic pain and nausea/vomiting and requires timely evaluation because torsion is a surgical diagnosis."},"V2-Q0833":{"stem":"A client with a positive pregnancy test has unilateral lower abdominal pain and vaginal bleeding. Which condition must be evaluated promptly?","key":"A","options":{"A":"Ectopic pregnancy, because pain and vaginal bleeding in early pregnancy can signal implantation outside the uterus and possible rupture.","B":"Normal implantation discomfort, because unilateral pain with bleeding is expected and does not require assessment for a pregnancy complication.","C":"Uncomplicated cystitis, because urinary infection is the primary explanation for unilateral pelvic pain with vaginal bleeding in pregnancy.","D":"Routine gastroenteritis, because gastrointestinal infection best explains vaginal bleeding in a client with a positive pregnancy test."},"authority":"P","source_name":"ACOG — Ectopic Pregnancy FAQ","source_url":"https://www.acog.org/womens-health/faqs/ectopic-pregnancy","source_locator":"Symptoms and diagnosis sections: abnormal vaginal bleeding and pelvic/abdominal pain are ectopic pregnancy warning symptoms; rupture can cause life-threatening internal bleeding.","source_version":"ACOG patient clinical FAQ, last reviewed April 2026; rechecked 2026-08-15.","finding":"A positive pregnancy test with unilateral pelvic or abdominal pain and vaginal bleeding warrants prompt evaluation for ectopic pregnancy because rupture can cause life-threatening hemorrhage."},"V2-Q0834":{"stem":"A third-trimester client has right upper-quadrant pain, nausea, malaise, hemolysis, elevated liver enzymes, and thrombocytopenia. Which complication is most consistent with these findings?","key":"A","options":{"A":"HELLP syndrome, a severe pregnancy complication characterized by hemolysis, elevated liver enzymes, and a low platelet count.","B":"Uncomplicated viral gastroenteritis, which does not account for the characteristic hemolysis, liver-enzyme elevation, and thrombocytopenia.","C":"Isolated gallbladder disease, which may cause right upper-quadrant pain but does not explain the complete HELLP laboratory pattern.","D":"Normal third-trimester physiology, because these laboratory abnormalities and upper-abdominal symptoms are not expected findings of healthy pregnancy."},"authority":"P","source_name":"ACOG — Preeclampsia and High Blood Pressure During Pregnancy","source_url":"https://www.acog.org/womens-health/faqs/preeclampsia-and-high-blood-pressure-during-pregnancy","source_locator":"HELLP syndrome section: hemolysis, elevated liver enzymes, and low platelet count; upper-abdominal pain, nausea, vomiting, headache, or malaise can occur.","source_version":"Current ACOG patient guidance accessed and rechecked 2026-08-15.","finding":"The combination of hemolysis, elevated liver enzymes, thrombocytopenia, and upper-abdominal symptoms is characteristic of HELLP syndrome and requires urgent obstetric evaluation."},"V2-Q0835":{"stem":"A client develops sudden severe diffuse abdominal pain, fever, tachycardia, and a rigid board-like abdomen. Which complication is most concerning?","key":"C","options":{"A":"Simple constipation, which can cause discomfort but does not typically produce a rigid abdomen with systemic inflammatory signs.","B":"Localized skin infection, which would not explain sudden diffuse abdominal pain and board-like abdominal rigidity.","C":"Peritonitis from possible gastrointestinal perforation, which requires immediate evaluation and treatment as an abdominal emergency.","D":"Expected postoperative discomfort, which should not be assumed when severe diffuse pain, fever, tachycardia, and rigidity are present."},"authority":"P","source_name":"NIH MedlinePlus — Gastrointestinal Perforation","source_url":"https://medlineplus.gov/ency/article/000235.htm","source_locator":"Symptoms and treatment sections: severe abdominal pain, tenderness, rigid abdomen, fever and shock can occur with perforation; immediate emergency treatment is required.","source_version":"NIH MedlinePlus Medical Encyclopedia page reviewed 2026-08-15.","finding":"Sudden severe diffuse pain with fever, tachycardia and board-like rigidity is concerning for peritonitis, including from gastrointestinal perforation, and warrants emergency evaluation."},"V2-Q0836":{"stem":"Why are young infants particularly vulnerable to clinically important temperature instability?","key":"D","options":{"A":"They regulate body temperature as efficiently as adults, so environmental exposure has little effect on their core temperature.","B":"Their normal temperature is always substantially lower than an adult's, making low readings expected in healthy infants.","C":"Their temperature should be interpreted with one fixed adult threshold regardless of age, measurement site, or clinical context.","D":"Their thermoregulation is less mature, so they can lose or gain heat rapidly and require age-appropriate temperature assessment."},"authority":"P","source_name":"American Academy of Pediatrics — Hypothermia in Young Infants","source_url":"https://publications.aap.org/pediatricsinreview/article/47/3/179/206733/Hypothermia-in-Young-Infants","source_locator":"Pediatrics in Review discussion of neonatal/young-infant thermoregulation: immature thermoregulatory mechanisms and higher surface-area-to-mass ratio increase susceptibility to heat loss.","source_version":"AAP Pediatrics in Review, 2026 volume 47 issue 3; rechecked 2026-08-15.","finding":"Young infants have immature thermoregulation and physiologic features that increase susceptibility to temperature instability; temperature must be interpreted in age and measurement context."},"V2-Q0837":{"stem":"An oncology regimen prescribes a medication dose in mg/m². Which nursing action correctly uses body surface area (BSA) dosing?","key":"C","options":{"A":"Substitute a simple mg/kg calculation, because BSA-based oncology regimens are interchangeable with weight-only dosing.","B":"Increase the calculated dose when renal or hepatic function declines, because BSA automatically compensates for impaired clearance.","C":"Calculate the ordered dose from the client's current BSA and prescribed mg/m², then apply regimen-specific dose adjustments and limits.","D":"Use BSA as a direct measure of organ clearance, because the calculated surface area independently predicts how every antineoplastic drug is eliminated."},"authority":"P","source_name":"FDA — Optimizing Dosage for Oncologic Diseases","source_url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/optimizing-dosage-human-prescription-drugs-and-biological-products-treatment-oncologic-diseases","source_locator":"Final guidance discusses dosage selection and optimization for oncology products and the need to use regimen- and patient-specific evidence rather than assuming one body-size metric guarantees optimal exposure.","source_version":"FDA final guidance, August 2024; current FDA page rechecked 2026-08-15.","finding":"When a regimen is ordered in mg/m², the nurse calculates the dose from current BSA and the prescribed mg/m², while recognizing that organ function, toxicity, maximum doses and regimen-specific adjustments remain separate clinical considerations."},"V2-Q0838":{"stem":"A nursing student asks what a medication's elimination half-life means. Which explanation is correct?","key":"A","options":{"A":"It is the time required for the amount or plasma concentration of a drug to decrease by approximately one half during elimination.","B":"It is the exact interval that must separate every two doses, regardless of the drug's formulation or therapeutic target.","C":"It is the total time until every molecule of the drug has been eliminated from the body with no residual amount remaining.","D":"It is a concept that applies only to intravenous medications and does not describe oral or other systemically absorbed drugs."},"authority":"S","source_name":"NCBI StatPearls — Elimination Half-Life of Drugs","source_url":"https://www.ncbi.nlm.nih.gov/books/NBK554498/","source_locator":"Definition section: elimination half-life is the time required for drug concentration in plasma or total amount in the body to decrease by 50 percent.","source_version":"NCBI Bookshelf StatPearls chapter, live clinical reference rechecked 2026-08-15.","finding":"Elimination half-life describes the time for the drug amount or plasma concentration to fall by about 50%; it is not synonymous with a dosing interval or complete elimination time."},"V2-Q0839":{"stem":"Why do narrow-therapeutic-index (NTI) drugs require especially careful dose and exposure control?","key":"A","options":{"A":"Small changes in dose or systemic exposure can produce clinically important loss of efficacy or toxicity because the therapeutic window is narrow.","B":"They have no measurable therapeutic range, so dosing is selected without reference to exposure, response, or toxicity.","C":"They are always more potent than other drugs, and potency alone determines whether therapeutic drug monitoring is required.","D":"They have a very wide separation between effective and toxic exposure, so modest changes in concentration rarely matter clinically."},"authority":"P","source_name":"FDA — Narrow Therapeutic Index Drugs","source_url":"https://www.fda.gov/drugs/cder-conversations/setting-and-implementing-standards-narrow-therapeutic-index-drugs","source_locator":"FDA CDER discussion of NTI drugs: small differences in dose or blood concentration may lead to serious therapeutic failures or adverse drug reactions.","source_version":"Current FDA CDER NTI standards page rechecked 2026-08-15.","finding":"NTI drugs have a narrow margin between concentrations associated with efficacy and those associated with toxicity or therapeutic failure, so small exposure changes can be clinically important."},"V2-Q0840":{"stem":"What is the primary purpose of a loading dose in pharmacotherapy?","key":"B","options":{"A":"To maintain an already established steady-state concentration with the same dose repeated indefinitely at each dosing interval.","B":"To reach a desired therapeutic concentration more rapidly by giving an initial dose calculated for the target concentration and distribution volume.","C":"To reduce the amount of drug initially administered so the concentration rises more slowly than it would with maintenance dosing alone.","D":"To replace all subsequent maintenance dosing because a loading dose is designed to remain indefinitely at therapeutic concentrations."},"authority":"S","source_name":"NCBI StatPearls — Loading Dose","source_url":"https://www.ncbi.nlm.nih.gov/books/NBK557418/","source_locator":"Pharmacokinetic dosing section: loading dose is used to attain a target concentration promptly and depends principally on volume of distribution and desired concentration.","source_version":"NCBI Bookshelf StatPearls clinical reference rechecked 2026-08-15.","finding":"A loading dose is an initial dose intended to achieve the target concentration promptly; maintenance dosing then replaces drug eliminated over time."},"V2-Q0841":{"stem":"A client has reduced kidney function and is prescribed a medication substantially eliminated by the kidneys. Which principle is most important?","key":"C","options":{"A":"Renal impairment routinely increases drug clearance, so doses should generally be increased to prevent subtherapeutic exposure.","B":"Kidney function is irrelevant when a drug is renally eliminated because dosing frequency alone determines systemic exposure.","C":"Reduced renal clearance can increase drug exposure, so dose or interval may need adjustment using drug-specific renal-function guidance.","D":"All renally eliminated drugs require the same fixed percentage dose reduction, regardless of the degree of impairment or drug characteristics."},"authority":"P","source_name":"FDA — Pharmacokinetics in Patients with Impaired Renal Function","source_url":"https://www.fda.gov/regulatory-information/search-fda-guidance-documents/pharmacokinetics-patients-impaired-renal-function-study-design-data-analysis-and-impact-dosing","source_locator":"Final guidance addresses how impaired renal function can alter pharmacokinetics and how renal-function information should support dosage recommendations for affected drugs.","source_version":"FDA final guidance, March 2024; current FDA page rechecked 2026-08-15.","finding":"For drugs substantially cleared by the kidneys, renal impairment can increase exposure; dosage or interval adjustments must follow drug-specific pharmacokinetic evidence and the patient's renal function."},"V2-Q0842":{"stem":"Before discharge teaching, which assessment best determines a client's readiness and ability to learn?","key":"A","options":{"A":"Assess pain, fatigue, emotional state, motivation, language and health-literacy needs, then choose timing and teaching methods accordingly.","B":"Assess only years of formal education because current symptoms, stress, language and motivation do not materially affect learning.","C":"Teach immediately whenever staff time is available, even if pain, fatigue or distress prevents the client from attending to the information.","D":"Skip readiness assessment because hospitalized adults can absorb and retain the same amount of information at any point during illness."},"authority":"P","source_name":"AHRQ — Health Literacy Universal Precautions Toolkit","source_url":"https://www.ahrq.gov/health-literacy/improve/precautions/tool12.html","source_locator":"Tool 12 / patient education guidance: assess understanding, use patient-centered communication and teach-back, and adapt education to the patient's needs and ability to engage.","source_version":"AHRQ Health Literacy Universal Precautions Toolkit page rechecked 2026-08-15.","finding":"Effective patient education is individualized to the patient's ability to engage and understand; symptoms, distress, fatigue, language, motivation and health-literacy needs influence timing and method."},"V2-Q0843":{"stem":"Which approach is most consistent with effective hospital discharge education?","key":"D","options":{"A":"Save all discharge teaching for the final few minutes before departure so information is delivered in one concentrated session.","B":"Provide education only if the client asks specific questions because proactive discharge preparation is unnecessary.","C":"Rely primarily on written instructions at departure and avoid involving the client or family earlier during hospitalization.","D":"Begin discharge preparation early, reinforce key information during the stay, and confirm understanding before the client leaves."},"authority":"P","source_name":"AHRQ — IDEAL Discharge Planning","source_url":"https://www.ahrq.gov/patient-safety/patients-families/engagingfamilies/strategy4/index.html","source_locator":"IDEAL Discharge Planning strategy: include patient/family as full partners, discuss key areas throughout the hospital stay, educate in plain language, assess understanding, and listen to goals/preferences.","source_version":"AHRQ patient/family engagement discharge strategy, current page rechecked 2026-08-15.","finding":"Discharge education should be an ongoing process during hospitalization, with repeated discussion, patient/family engagement and confirmation of understanding rather than a last-minute information dump."},"V2-Q0844":{"stem":"Which factor should most directly guide selection of a medication's route of administration?","key":"A","options":{"A":"The desired onset, medication properties, clinical condition, swallowing or access limitations, and safety of the available routes.","B":"The least expensive route for the facility, regardless of the needed onset, medication formulation or patient's condition.","C":"One standard route for all clients because route selection does not materially affect absorption, onset or treatment feasibility.","D":"The patient's preference alone, even when the formulation cannot be safely or effectively administered by the preferred route."},"authority":"S","source_name":"NCBI StatPearls — Medication Routes of Administration","source_url":"https://www.ncbi.nlm.nih.gov/books/NBK568677/","source_locator":"Route-selection overview: route depends on drug properties, therapeutic objectives, patient condition and feasibility; routes differ in onset, bioavailability and practical limitations.","source_version":"NCBI Bookshelf StatPearls clinical reference rechecked 2026-08-15.","finding":"Medication route selection is clinical and drug-specific, considering desired onset, formulation/pharmacokinetics, patient condition, route feasibility and safety rather than cost or preference alone."},"V2-Q0845":{"stem":"An unresponsive client is breathing normally and has no suspected spine or major trauma. Which position helps maintain an open airway while awaiting further care?","key":"D","options":{"A":"Flat supine with the head fixed straight, because this reliably prevents secretions or vomit from entering the airway in an unresponsive person.","B":"High-Fowler position without support, because an unresponsive client can reliably maintain trunk and airway alignment while seated upright.","C":"Prone face-down with the airway covered, because this position is recommended to prevent aspiration in all unconscious clients.","D":"A side-lying recovery position that maintains airway patency and permits fluid to drain, while continuing to monitor breathing."},"authority":"P","source_name":"AHA/American Red Cross — 2024 First Aid Guidelines","source_url":"https://cpr.heart.org/en/resuscitation-science/2024-first-aid-guidelines","source_locator":"Recovery position recommendation: place an unresponsive person who is breathing normally and does not require CPR in a side-lying recovery position when no condition requires keeping them supine.","source_version":"2024 American Heart Association/American Red Cross First Aid Guidelines; rechecked 2026-08-15.","finding":"For an unresponsive person breathing normally without a contraindication to movement, the recovery position is side-lying to help maintain airway patency and drainage while breathing is monitored."},"V2-Q0846":{"stem":"Under U.S. federal Vaccine Information Statement (VIS) recordkeeping requirements, which information must be documented in the permanent medical record after vaccination?","key":"C","options":{"A":"Only the vaccination date and injection site, because manufacturer, lot number, VIS information and vaccinator identification are optional.","B":"Only the vaccine brand and dose volume, because federal VIS recordkeeping does not require identifying the lot or the person administering it.","C":"Administration date, manufacturer and lot number, vaccinator's name/address/title, plus the VIS edition date and date it was provided.","D":"The client's signature accepting vaccination and insurance authorization number, because these replace the product and VIS documentation requirements."},"authority":"P","source_name":"CDC — Instructions for Using Vaccine Information Statements","source_url":"https://www.cdc.gov/vaccines/hcp/about-vis/instructions.html","source_locator":"Recordkeeping section under the National Childhood Vaccine Injury Act: record administration date, manufacturer, lot number, name/address/title of administrator, VIS edition date, and date VIS provided.","source_version":"CDC VIS instructions, page updated/reviewed May 29, 2025; rechecked 2026-08-15.","finding":"Federal VIS recordkeeping requires documentation of administration date, manufacturer, lot number, administrator identity/address/title, VIS edition date, and date the VIS was provided; site and route may be documented clinically but are not the complete federal statutory set."},"V2-Q0847":{"stem":"How should evidence-based preventive screening recommendations generally be applied to an asymptomatic adult?","key":"C","options":{"A":"Delay screening until symptoms develop because preventive recommendations are not intended for people without symptoms.","B":"Use one identical schedule for every adult because age, sex, pregnancy status and individual risk do not modify recommendations.","C":"Apply the recommendation for the person's age and population group, then account for individual risk factors and the specific guideline criteria.","D":"Avoid screening in healthy adults because preventive testing is recommended only after a clinician has already diagnosed the target disease."},"authority":"P","source_name":"USPSTF — A and B Preventive Recommendations","source_url":"https://www.uspreventiveservicestaskforce.org/uspstf/recommendation-topics/uspstf-a-and-b-recommendations","source_locator":"USPSTF recommendation table specifies preventive services by population, age/sex or pregnancy status and risk criteria, with recommendation-specific applicability for asymptomatic people.","source_version":"Current USPSTF A/B recommendation index rechecked 2026-08-15.","finding":"Preventive screening is recommendation-specific and population-specific; clinicians apply age/sex/pregnancy and risk criteria rather than waiting for symptoms or using one universal schedule."},"V2-Q0848":{"stem":"Which household intervention is appropriate for preventing common injuries in young children?","key":"D","options":{"A":"Leave unstable furniture unsecured because tip-over injuries are unlikely when adults are present elsewhere in the home.","B":"Store medications and cleaning products in reachable cabinets so children can learn which containers they should not touch.","C":"Rely on verbal warnings alone and remove smoke alarms or outlet protections once a child can walk independently.","D":"Anchor tip-prone furniture, secure hazardous products, maintain smoke alarms, and use age-appropriate barriers or outlet protection."},"authority":"P","source_name":"U.S. Consumer Product Safety Commission — Childproofing Your Home","source_url":"https://www.cpsc.gov/safety-education/safety-guides/kids-and-babies/Childproofing-Your-Home","source_locator":"CPSC childproofing recommendations address furniture/TV anchoring, locked storage of medicines and household chemicals, smoke alarms and age-appropriate home safety devices.","source_version":"Current U.S. CPSC childproofing safety guide rechecked 2026-08-15.","finding":"Young-child injury prevention uses layered environmental controls such as anchoring furniture, securing toxic products and medicines, maintaining smoke alarms and using age-appropriate barriers and outlet protection."},"V2-Q0849":{"stem":"A nurse develops an unusually strong emotional response to a client that is shaped by the nurse's own past relationships. What is this phenomenon?","key":"D","options":{"A":"Transference, in which the client's past relationship patterns are redirected toward the clinician rather than originating primarily from the clinician.","B":"Therapeutic empathy, because any strong personal reaction based on the nurse's own history is expected and does not require self-awareness.","C":"Projection by the client, in which the client attributes personal feelings to others rather than the nurse reacting from unresolved experiences.","D":"Countertransference, in which the clinician's own feelings, experiences or unresolved conflicts influence reactions toward the client."},"authority":"S","source_name":"Open RN/NCBI Bookshelf — Therapeutic Nurse-Client Relationship","source_url":"https://www.ncbi.nlm.nih.gov/books/NBK590042/","source_locator":"Therapeutic relationship discussion distinguishes countertransference as the nurse's feelings or behaviors toward a client influenced by the nurse's prior relationships or experiences.","source_version":"Open RN Mental Health and Community Concepts via NCBI Bookshelf; rechecked 2026-08-15.","finding":"Countertransference occurs when the clinician's own prior experiences or unresolved feelings shape emotional responses to the client; recognition and professional self-awareness are needed to protect clinical judgment."},"V2-Q0850":{"stem":"A client responds to the nurse as though the nurse were a significant person from the client's past. What is this phenomenon?","key":"A","options":{"A":"Transference, in which feelings and expectations connected to an earlier significant relationship are redirected toward the current clinician.","B":"Countertransference, in which the clinician's own prior experiences shape the clinician's emotional response toward the client.","C":"Malingering, in which symptoms are intentionally produced for an external incentive rather than arising from relationship dynamics.","D":"Delirium, in which acute fluctuating inattention and cognition explain the client's behavior rather than redirected relational feelings."},"authority":"S","source_name":"Open RN/NCBI Bookshelf — Therapeutic Relationship Concepts","source_url":"https://www.ncbi.nlm.nih.gov/books/NBK590040/","source_locator":"Therapeutic relationship section defines transference as a client's transfer of feelings associated with significant people in the past onto the nurse or other current caregiver.","source_version":"Open RN Mental Health and Community Concepts via NCBI Bookshelf; rechecked 2026-08-15.","finding":"Transference is the redirection of feelings or expectations from an important past relationship onto the current clinician; it is not by itself evidence of a personality disorder."},"V2-Q0851":{"stem":"During a stressful hospitalization, an adult begins using markedly childlike and dependent behaviors. Which defense mechanism may explain this response?","key":"D","options":{"A":"Sublimation, in which an unacceptable impulse is redirected into a socially acceptable or constructive activity.","B":"Projection, in which a person attributes their own unacceptable thoughts or feelings to another person.","C":"Rationalization, in which a person creates a plausible explanation to avoid the more uncomfortable reason for a behavior.","D":"Regression, in which stress is managed by reverting to behaviors or coping patterns associated with an earlier developmental stage."},"authority":"S","source_name":"Open RN/NCBI Bookshelf — Defense Mechanisms Table","source_url":"https://www.ncbi.nlm.nih.gov/books/NBK616983/table/ch3.tab1/","source_locator":"Defense-mechanism table defines regression as reverting to an earlier stage or less mature behavior in response to anxiety or stress.","source_version":"Open RN psychiatric nursing content, 2025 NCBI Bookshelf edition; rechecked 2026-08-15.","finding":"Regression is an often-unconscious return to earlier or less mature patterns of behavior under stress; it should not automatically be labeled intentional attention-seeking or malingering."},"V2-Q0852":{"stem":"A client with edema and chronic kidney disease is prescribed furosemide. Which nursing principle is most accurate?","key":"A","options":{"A":"Evaluate diuretic response, kidney function, volume status and electrolytes because dose requirements and safety vary with the patient's clinical condition.","B":"Assume a standard dose will produce the same diuresis at every level of kidney function, so renal status does not affect monitoring or response.","C":"Withhold furosemide solely because chronic kidney disease is present, because loop diuretics are contraindicated whenever renal function is reduced.","D":"Replace furosemide automatically with a thiazide because thiazides always produce greater natriuresis than loop diuretics in advanced kidney disease."},"authority":"P","source_name":"DailyMed — Furosemide Tablets Prescribing Information","source_url":"https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=462e8917-cbe0-f4f9-e063-6394a90ab4ff","source_locator":"Dosage/administration and warnings sections: therapy is individualized; monitor fluid/electrolyte balance and renal function, with dosage titrated to response and clinical need.","source_version":"DailyMed FDA labeling, updated June 17, 2026; rechecked 2026-08-15.","finding":"Furosemide dosing and monitoring are individualized; kidney function, volume status, electrolyte balance and clinical diuretic response matter. A categorical claim that one diuretic class is always effective or ineffective at a given renal level is inappropriate."},"V2-Q0853":{"stem":"A male client taking spironolactone develops breast tenderness and enlargement. Which interpretation is most appropriate?","key":"A","options":{"A":"Gynecomastia is a recognized spironolactone adverse effect and should be reported for medication assessment if clinically significant or bothersome.","B":"This finding proves an immediate IgE-mediated allergy and requires epinephrine even without airway, skin or circulatory features of anaphylaxis.","C":"This finding confirms breast cancer because medication-related breast enlargement is not associated with spironolactone therapy.","D":"The symptom is unrelated to spironolactone, so the medication should never be considered during assessment of new breast enlargement or tenderness."},"authority":"P","source_name":"DailyMed — Spironolactone Tablets","source_url":"https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=eb314e91-6dd5-4bdb-af35-5d147b20339c","source_locator":"Adverse reactions/warnings: spironolactone can cause gynecomastia; risk is related to dosage level and duration and is usually reversible after discontinuation.","source_version":"DailyMed FDA labeling revised May 2026; rechecked 2026-08-15.","finding":"Gynecomastia and breast tenderness are recognized spironolactone adverse effects and merit medication assessment; the finding alone neither proves allergy nor cancer."},"V2-Q0854":{"stem":"A client taking allopurinol develops a new rash. Which action is most appropriate?","key":"C","options":{"A":"Continue the medication and use only an over-the-counter cream because allopurinol rashes cannot progress to serious cutaneous reactions.","B":"Double the next dose because a rash usually indicates inadequate urate lowering rather than a possible drug hypersensitivity reaction.","C":"Stop allopurinol and seek prompt clinical evaluation because serious hypersensitivity and severe cutaneous adverse reactions can begin with a rash.","D":"Ignore the rash unless joint pain returns because skin findings are not included among clinically important adverse reactions to allopurinol."},"authority":"P","source_name":"DailyMed — Allopurinol Tablets","source_url":"https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=5dca2d4f-0e93-4d1a-8d9f-b9b72867c242&version=103","source_locator":"Warnings and precautions: discontinue allopurinol permanently at the first appearance of skin rash or other signs that may indicate hypersensitivity; serious and sometimes fatal reactions including SJS/TEN are described.","source_version":"DailyMed allopurinol label version 103, current in 2026; rechecked 2026-08-15.","finding":"A new rash during allopurinol therapy requires prompt action because labeling directs discontinuation at the first rash/sign of hypersensitivity and warns of severe cutaneous reactions including SJS/TEN."},"V2-Q0855":{"stem":"Which statement best describes methotrexate's antineoplastic mechanism at higher-dose cancer therapy?","key":"A","options":{"A":"It acts as an antifolate that inhibits dihydrofolate reductase and folate-dependent pathways needed for nucleotide and DNA synthesis.","B":"It works exclusively by inhibiting cyclooxygenase like an NSAID and has no clinically relevant effect on folate-dependent nucleotide synthesis.","C":"It kills bacteria by disrupting bacterial cell walls and is therefore classified primarily as a beta-lactam antimicrobial medication.","D":"It directly stimulates DNA polymerase and accelerates DNA synthesis in rapidly dividing cells, which is the opposite of its antimetabolite action."},"authority":"P","source_name":"DailyMed — Methotrexate Tablets","source_url":"https://www.dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a63364d5-4dfa-49d7-8a5e-c8959ae1d37a","source_locator":"Clinical pharmacology/mechanism section: methotrexate inhibits dihydrofolate reductase and interferes with folate-dependent processes required for purine, thymidylate and DNA synthesis.","source_version":"DailyMed FDA labeling updated in 2026; rechecked 2026-08-15.","finding":"Methotrexate is an antifolate antimetabolite affecting folate-dependent nucleotide and DNA synthesis; its mechanisms in inflammatory disease are more complex than simply acting like an NSAID."},"V2-Q0856":{"stem":"A client reports a prior immediate allergy to a sulfonamide antibiotic. Another sulfonamide-containing medication is being considered. Which nursing interpretation is most accurate?","key":"D","options":{"A":"All drugs containing any sulfonamide group are automatically cross-reactive, so every nonantibiotic sulfonamide is absolutely contraindicated.","B":"The allergy can be ignored because a prior immediate reaction to a sulfonamide antibiotic has no relevance to future medication assessment.","C":"Only the exact same brand can cause a repeat reaction, so the chemical class and the nature of the prior reaction do not need to be reviewed.","D":"Clarify the culprit and reaction; broad cross-reactivity with nonantibiotic sulfonamides is not expected, but the specific drug still needs individual assessment."},"authority":"P","source_name":"AAAAI/ACAAI — 2022 Drug Allergy Practice Parameter Update","source_url":"https://www.allergyparameters.org/parameters-and-guidelines/drug/2022-drug-allergy-update","source_locator":"Sulfonamide allergy guidance: structural determinants of sulfonamide antimicrobial allergy differ from nonantimicrobial sulfonamides; broad allergic cross-reactivity is not supported, while history and specific drug/reaction remain important.","source_version":"2022 Drug Allergy Practice Parameter Update; current parameter page rechecked 2026-08-15.","finding":"A sulfonamide-antibiotic allergy should be characterized by culprit and reaction. It does not justify assuming universal immunologic cross-reactivity with all nonantibiotic sulfonamides, though each proposed drug must still be assessed on its own risks."},"V2-Q0857":{"stem":"A client reports a prior penicillin allergy and is prescribed a cephalosporin. Which assessment principle is most accurate?","key":"B","options":{"A":"Every cephalosporin is absolutely contraindicated after any penicillin reaction, regardless of reaction type, side chain or cephalosporin generation.","B":"Assess the reaction history and planned agent; later-generation cephalosporins have low IgE cross-reactivity, while severe delayed reactions require special caution.","C":"Penicillin and cephalosporins have zero possible cross-reactivity, so allergy history never affects antibiotic selection or monitoring.","D":"Cross-reactivity is determined only by whether the two drug names sound similar, not by beta-lactam structure, side chains or the prior immune reaction."},"authority":"P","source_name":"CDC — Penicillin Allergy and Cephalosporin Cross-Reactivity","source_url":"https://www.cdc.gov/std/treatment-guidelines/penicillin-allergy.htm","source_locator":"Cross-reactivity section: third-generation cephalosporins have lower cross-reactivity with IgE-mediated penicillin allergy (<1%) than first/second generation; severe non-IgE reactions require different management.","source_version":"CDC STI Treatment Guidelines penicillin-allergy page, current guidance rechecked 2026-08-15.","finding":"Cephalosporin use after a penicillin allergy depends on the specific prior reaction and cephalosporin. Later-generation agents have low IgE cross-reactivity, while severe delayed beta-lactam reactions warrant avoidance/specialist guidance."},"V2-Q0858":{"stem":"Why is an aminoglycoside such as gentamicin concerning in a client with myasthenia gravis?","key":"A","options":{"A":"Aminoglycosides can impair neuromuscular transmission and may intensify weakness or produce neuromuscular blockade in susceptible clients.","B":"Aminoglycosides increase acetylcholine release and are first-line treatment for the underlying autoimmune neuromuscular-junction disorder.","C":"Gentamicin has no clinically relevant effect on neuromuscular function, so myasthenia gravis does not influence risk assessment.","D":"The principal concern is predictable severe hypertension from aminoglycoside therapy rather than worsening neuromuscular weakness or blockade."},"authority":"P","source_name":"DailyMed — Gentamicin Injection","source_url":"https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=977180b3-a222-4282-d485-4a3217674305","source_locator":"Warnings/precautions: aminoglycosides have neuromuscular-blocking properties and should be used cautiously in disorders characterized by muscular weakness such as myasthenia gravis.","source_version":"Current DailyMed gentamicin injection labeling rechecked 2026-08-15.","finding":"Gentamicin and other aminoglycosides can impair neuromuscular transmission and worsen weakness or neuromuscular blockade in myasthenia gravis, so the order requires careful risk review."},"V2-Q0859":{"stem":"A client with COPD has a strong cardiovascular indication for beta-blocker therapy. Which approach aligns with current COPD guidance?","key":"A","options":{"A":"Use a cardioselective beta-blocker when beta-blockade is indicated for cardiovascular disease, with clinical monitoring and individualized risk assessment.","B":"Avoid all beta-blockers in every person with COPD because even cardioselective agents are universally contraindicated regardless of cardiac need.","C":"Start a nonselective beta-blocker solely to prevent COPD exacerbations, even when the client has no cardiovascular indication for beta-blockade.","D":"Choose a beta-blocker without considering pulmonary effects, selectivity or cardiovascular indication because COPD never influences medication selection."},"authority":"P","source_name":"GOLD — Global Strategy for COPD 2026","source_url":"https://goldcopd.org/2026-gold-report-and-pocket-guide/","source_locator":"Comorbid cardiovascular disease/beta-blocker guidance: cardioselective beta-blockers are preferred when a clear cardiovascular indication exists; beta-blockers are not recommended solely to prevent COPD exacerbations without such an indication.","source_version":"GOLD 2026 Report and Pocket Guide; current release rechecked 2026-08-15.","finding":"COPD is not an automatic contraindication to indicated beta-blockade. Current GOLD guidance favors cardioselective agents for established cardiovascular indications and does not support beta-blockers solely to prevent COPD exacerbations."},"V2-Q0860":{"stem":"Why does mild renal impairment matter when an older adult is prescribed digoxin?","key":"C","options":{"A":"Digoxin is eliminated entirely by hepatic metabolism, so reduced kidney function cannot increase systemic exposure or toxicity risk.","B":"Older adults require higher routine digoxin doses because age-related reductions in renal function consistently lower serum digoxin concentrations.","C":"Digoxin is substantially renally eliminated, so reduced renal function can prolong elimination and increase exposure unless dosing is adjusted appropriately.","D":"Renal function affects only the tablet's absorption from the intestine and does not influence digoxin clearance after the drug enters circulation."},"authority":"P","source_name":"DailyMed — Digoxin Tablets","source_url":"https://dailymed.nlm.nih.gov/dailymed/lookup.cfm?setid=5b2d10d0-6e9d-4c39-a025-6b2f30ff6243","source_locator":"Clinical pharmacology/specific populations: digoxin is primarily excreted by the kidneys; clearance correlates with creatinine clearance, and impaired renal function requires smaller maintenance doses and longer time to steady state.","source_version":"DailyMed digoxin labeling updated January 13, 2026; rechecked 2026-08-15.","finding":"Digoxin is substantially eliminated by the kidneys, so renal impairment can prolong its half-life and increase exposure; maintenance dosing must account for renal function, age, body size and clinical response."},"V2-Q0861":{"stem":"A nurse is preparing a syringe containing regular insulin and NPH insulin. Which sequence is appropriate when the products are ordered to be mixed?","key":"B","options":{"A":"Withdraw NPH before regular insulin so cloudy suspension enters the regular-insulin vial first and standardizes future doses.","B":"Withdraw regular insulin before NPH insulin, using the recommended mixing sequence so the clear regular-insulin vial is not contaminated with NPH.","C":"Shake both insulin vials vigorously and combine them in a separate container before withdrawing the final dose into the syringe.","D":"Mix any insulin types in any order because all insulin formulations are compatible in one syringe and sequence never affects product integrity."},"authority":"P","source_name":"DailyMed — Humulin N Prescribing Information","source_url":"https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=f6edd793-440b-40c2-96b5-c16133b7a921","source_locator":"Administration instructions for mixing with regular insulin: draw regular insulin into the syringe first, followed by HUMULIN N; administer immediately after mixing.","source_version":"Current FDA/DailyMed Humulin N prescribing information rechecked 2026-08-15.","finding":"When regular insulin and NPH are specifically ordered to be mixed, labeling instructs drawing regular insulin first and NPH second, then administering the mixture promptly."},"V2-Q0862":{"stem":"Which set of practices is included in CDC Standard Precautions for routine patient care?","key":"B","options":{"A":"Precautions applied only after a laboratory confirms a transmissible infection, with no measures used for other patients.","B":"Hand hygiene, exposure-based PPE, respiratory hygiene, injection safety, and safe handling of contaminated equipment and surfaces.","C":"Hand hygiene alone, because PPE, respiratory hygiene, sharps safety and injection practices are separate from Standard Precautions.","D":"Airborne isolation for every patient, including respirators and negative-pressure rooms regardless of diagnosis or anticipated exposure."},"authority":"P","source_name":"CDC — Standard Precautions for All Patient Care","source_url":"https://www.cdc.gov/infection-control/hcp/basics/standard-precautions.html","source_locator":"Standard Precautions page lists hand hygiene, PPE based on exposure risk, respiratory hygiene/cough etiquette, sharps safety, safe injection practices, sterile instruments/devices and environmental cleaning.","source_version":"Current CDC infection-control guidance rechecked 2026-08-15.","finding":"Standard Precautions apply to all patient care and include hand hygiene, risk-based PPE, respiratory hygiene, injection/sharps safety, equipment reprocessing and environmental cleaning."},"V2-Q0863":{"stem":"When removing a contaminated isolation gown, which technique best reduces self-contamination?","key":"A","options":{"A":"Handle the contaminated outer surface as little as possible, turn the gown inward while removing it, and keep the contaminated surface away from clothing and skin.","B":"Grasp the contaminated front with bare hands and pull it across the face because the gown's outer surface is considered clean during removal.","C":"Keep the used gown on while walking through the hallway so contamination remains contained until the nurse reaches a central disposal area.","D":"Remove the gown in a way that lets the outer contaminated surface brush the uniform, because clothing contact is not a recognized self-contamination pathway."},"authority":"P","source_name":"CDC — Isolation Precautions/PPE Removal","source_url":"https://www.cdc.gov/infection-control/hcp/isolation-precautions/prevention.html","source_locator":"PPE removal principles: remove and discard contaminated PPE to prevent contamination of clothing, skin or mucous membranes; gown removal turns the contaminated surface inward and avoids touching exposed surfaces.","source_version":"Current CDC Isolation Precautions prevention guidance rechecked 2026-08-15.","finding":"Gown doffing should minimize contact with the contaminated outer surface and turn the gown inward while keeping contamination away from skin and clothing; exact doffing sequence may vary by PPE ensemble/protocol."},"V2-Q0864":{"stem":"A nurse finds that the PPE needed for a client's Transmission-Based Precautions is not readily available before care. What is the best action?","key":"A","options":{"A":"Obtain or restore access to the indicated PPE before entering for anticipated exposure, and report supply problems through the facility process.","B":"Enter without the indicated PPE and obtain it later if visible contamination occurs, because precautions begin only after an exposure is seen.","C":"Ask staff to bring personal protective supplies from home because institutional PPE availability is not part of infection-control readiness.","D":"Ignore the shortage until the next shift because Transmission-Based Precautions do not require the appropriate PPE to be available before patient contact."},"authority":"P","source_name":"CDC — Transmission-Based Precautions","source_url":"https://www.cdc.gov/infection-control/hcp/basics/transmission-based-precautions.html","source_locator":"Transmission-Based Precautions guidance requires use of the indicated PPE in addition to Standard Precautions based on route of transmission; PPE should be donned before relevant patient/environment contact or exposure.","source_version":"Current CDC Transmission-Based Precautions page rechecked 2026-08-15.","finding":"The indicated PPE must be available and donned before anticipated exposure under Transmission-Based Precautions. A supply shortage should be corrected/escalated rather than bypassing required protection."},"V2-Q0865":{"stem":"What is the primary patient-safety purpose of USP <797> requirements for compounded sterile preparations?","key":"C","options":{"A":"To shorten preparation time even when faster workflow increases the risk of microbial, chemical or physical contamination.","B":"To regulate only nonsterile oral compounding and exclude parenteral or other compounded sterile preparations from quality requirements.","C":"To establish personnel, environmental, process and quality controls that reduce contamination and other risks in compounded sterile preparations.","D":"To eliminate all need for professional judgment because compliance with the chapter guarantees that no compounding error can ever occur."},"authority":"P","source_name":"USP — General Chapter <797> Pharmaceutical Compounding—Sterile Preparations","source_url":"https://doi.usp.org/USPNF/USPNF_M99925_09_01.html","source_locator":"USP <797> scope and purpose establish minimum standards for compounding sterile preparations to minimize harm including contamination, excessive endotoxins, variability and other quality failures.","source_version":"Official USP <797> chapter, current compounding standard including 2025 official text; rechecked 2026-08-15.","finding":"USP <797> establishes personnel, environmental, process and quality controls for compounded sterile preparations to reduce contamination and other compounding-related patient risks; its purpose is safety, not workflow speed."},"V2-Q0866":{"stem":"Why are many complex sterile IV admixtures prepared in a centralized pharmacy compounding area rather than at the bedside?","key":"D","options":{"A":"Central preparation removes the need for independent checks, standardized procedures or environmental controls because pharmacists alone prevent all errors.","B":"Central pharmacy compounding is intended only for oral products and offers no role in preparing sterile parenteral medications.","C":"The main goal is to delay medication delivery so nursing staff have more time before administering time-sensitive therapy.","D":"Controlled facilities, trained compounding personnel, standardized processes and verification can reduce contamination and preparation-error risks."},"authority":"P","source_name":"ASHP — Compounding Resource Center","source_url":"https://www.ashp.org/pharmacy-practice/resource-centers/compounding","source_locator":"ASHP sterile compounding resources emphasize compliance with USP standards, controlled environments, trained personnel, standardized processes and medication-safety safeguards for compounded sterile preparations.","source_version":"Current ASHP compounding practice resources rechecked 2026-08-15.","finding":"Centralized sterile compounding uses trained personnel, controlled environments, standard procedures and verification to reduce preparation and contamination risk compared with unnecessary complex bedside compounding."},"V2-Q0867":{"stem":"Which pattern should prompt investigation for possible controlled-substance diversion rather than being dismissed because documentation appears complete?","key":"B","options":{"A":"Occasional variation in patient assignment with no discrepancy in controlled-substance transactions, wasting, access or medication administration patterns.","B":"Repeated unexplained count discrepancies, atypical access or administration patterns, or unusual controlled-substance wasting that departs from peers or workflow.","C":"A staff member accurately reconciles controlled-substance counts and has transaction patterns consistent with assigned patients and documented administration.","D":"A nurse has a shift without administering any controlled substance because absence of controlled-drug use by itself is evidence of diversion."},"authority":"P","source_name":"U.S. DEA — Health-Care Diversion Enforcement Example","source_url":"https://www.dea.gov/press-releases/2019/06/26/nurse-parker-adventist-hospital-pleads-guilty-stealing-fentanyl","source_locator":"DEA diversion case describes manipulation of controlled-substance dispensing/waste processes and discrepancies; such unexplained transactional patterns warrant institutional investigation rather than assumptions from paperwork alone.","source_version":"Official DEA diversion-control enforcement material; rechecked 2026-08-15.","finding":"Repeated unexplained controlled-substance discrepancies, atypical access/administration or unusual waste patterns are recognized diversion red flags that warrant investigation; no single pattern alone proves diversion."},"V2-Q0868":{"stem":"A partial dose of a controlled substance must be discarded after administration. Which approach is most accurate?","key":"D","options":{"A":"Discard it privately without documentation because once part of the dose is administered, the remainder is no longer subject to controlled-substance accountability.","B":"Keep the unused remainder for a later patient because controlled substances may be stored informally after a single-use dose has been opened.","C":"Assume federal DEA rules universally require the same bedside two-nurse witness process in every setting, regardless of state law or facility policy.","D":"Follow applicable federal, state and local requirements plus institutional policy for prompt disposal, documentation and any required witness or verification."},"authority":"P","source_name":"DEA Diversion Control — Drug Disposal Information","source_url":"https://www.deadiversion.usdoj.gov/faq/disp-destr-faq.html","source_locator":"DEA disposal/destruction guidance explains practitioner responsibilities and controlled-substance disposal pathways; healthcare-facility procedures also operate under applicable state/local requirements and institutional controls.","source_version":"Current DEA Diversion Control drug-disposal Q&A rechecked 2026-08-15.","finding":"Controlled-substance waste must be handled and documented under applicable federal, state/local and institutional requirements. A universal federal rule requiring the same second-nurse witness for every bedside partial dose should not be asserted without the governing policy."},"V2-Q0869":{"stem":"After a medication error, the organization examines workflow, staffing, technology, communication and human factors in addition to individual actions. What safety approach is this?","key":"D","options":{"A":"A punitive model that assumes one clinician is the sole cause and therefore excludes workflow, technology and environmental contributors from analysis.","B":"A process limited to events without patient harm because systems analysis cannot be used after serious adverse events.","C":"A documentation audit only, in which the investigation ends once the chart contains all required signatures and medication records.","D":"A systems-based event analysis that identifies contributing conditions and process failures so corrective actions can reduce recurrence."},"authority":"P","source_name":"AHRQ — CANDOR Event Investigation and Analysis","source_url":"https://www.ahrq.gov/patient-safety/settings/hospital/candor/modules/guide4.html","source_locator":"CANDOR Event Investigation and Analysis Guide emphasizes multidisciplinary systems analysis, contributing factors, human factors, process design and corrective actions rather than reflexive individual blame.","source_version":"AHRQ CANDOR Toolkit current module rechecked 2026-08-15.","finding":"Modern patient-safety investigation uses systems analysis to identify workflow, staffing, technology, communication and human-factor contributors while still addressing individual accountability when appropriate."},"V2-Q0870":{"stem":"Which behavior best reflects effective interprofessional team leadership in a hospital?","key":"C","options":{"A":"One profession makes all care decisions independently so other disciplines do not contribute information that could complicate the plan.","B":"Team members avoid clarifying roles because shared decision-making works best when responsibility remains intentionally ambiguous.","C":"Team members establish shared goals, invite relevant expertise, communicate openly, clarify roles and make coordinated decisions for patient care.","D":"Nursing input is reduced when medical staff are present because collaborative practice requires one profession to have exclusive control of decisions."},"authority":"P","source_name":"AHRQ TeamSTEPPS — Team Leadership Tools","source_url":"https://www.ahrq.gov/teamstepps-program/curriculum/team/tools/index.html","source_locator":"TeamSTEPPS team/leadership tools emphasize shared plan, clear roles/responsibilities, information sharing, mutual support, briefs/huddles/debriefs and coordinated team performance.","source_version":"Current AHRQ TeamSTEPPS 3.0 curriculum rechecked 2026-08-15.","finding":"Effective interprofessional collaboration uses shared goals, explicit roles, open information exchange, mutual respect/support and coordinated decision-making rather than suppressing one discipline's input."},"V2-Q0871":{"stem":"Which four teamwork skills are central to the AHRQ TeamSTEPPS framework?","key":"C","options":{"A":"Billing, coding, credentialing and utilization review, which are administrative functions rather than the core TeamSTEPPS teamwork skills.","B":"Diagnosis, prescribing, surgery and discharge, which are clinical activities rather than the framework's cross-disciplinary teamwork competencies.","C":"Communication, team leadership, situation monitoring and mutual support, which interact to support team performance and patient safety.","D":"Individual speed, hierarchy, competition and secrecy, which conflict with the framework's emphasis on coordinated team performance."},"authority":"P","source_name":"AHRQ — TeamSTEPPS 3.0 Overview","source_url":"https://www.ahrq.gov/teamstepps-program/curriculum/intro/overview.html","source_locator":"TeamSTEPPS framework overview identifies four core teamwork skills: Communication, Team Leadership, Situation Monitoring, and Mutual Support, with team structure central to their use.","source_version":"AHRQ TeamSTEPPS 3.0 current curriculum rechecked 2026-08-15.","finding":"TeamSTEPPS centers on four teamwork skills—communication, team leadership, situation monitoring and mutual support—used within a defined team structure to improve safety and performance."},"V2-Q0872":{"stem":"What is the primary purpose of a structured post-procedure team debrief?","key":"D","options":{"A":"To replace the preprocedure time-out and site verification because only one structured team communication step is needed for surgery.","B":"To identify one person to blame for any difficulty so the team can close the case without reviewing process or system opportunities.","C":"To document that the case ended on time, without discussing safety concerns, communication failures, equipment issues or improvement opportunities.","D":"To review what happened, identify concerns and lessons, recognize successes, and agree on improvements that can strengthen future team performance."},"authority":"P","source_name":"AHRQ TeamSTEPPS — Debrief Tool","source_url":"https://www.ahrq.gov/teamstepps-program/curriculum/team/tools/debrief.html","source_locator":"TeamSTEPPS debrief tool: a short information exchange after an event designed to improve team effectiveness by reviewing performance, identifying what went well and what should change.","source_version":"Current AHRQ TeamSTEPPS 3.0 debrief tool rechecked 2026-08-15.","finding":"A debrief is a structured post-event review of team performance, concerns, successes and lessons with the purpose of improving future performance; it does not replace the procedural time-out."},"V2-Q0873":{"stem":"A nursing team conducts a brief huddle to reassess workload, acuity and emerging safety concerns. What is the main purpose?","key":"D","options":{"A":"To replace all individual patient handoffs because a unit huddle contains every detail needed for continuity of care.","B":"To assign blame for problems identified during the shift before the team has assessed causes or possible solutions.","C":"To limit information sharing to managers because frontline team members should not update the shared plan during changing conditions.","D":"To update situational awareness, revise the plan when conditions change, and proactively identify resources or risks that need attention."},"authority":"P","source_name":"AHRQ TeamSTEPPS — Huddle/Teamwork Tools","source_url":"https://www.ahrq.gov/teamstepps-program/curriculum/team/overview/index.html","source_locator":"TeamSTEPPS team-event overview describes huddles as ad hoc planning/replanning opportunities used to establish situational awareness, reinforce plans and address emerging issues.","source_version":"Current AHRQ TeamSTEPPS 3.0 curriculum rechecked 2026-08-15.","finding":"A huddle is a brief team replanning tool used to restore shared situational awareness, adjust the plan and identify emerging safety/resource needs; it complements rather than replaces patient-specific handoff."},"V2-Q0874":{"stem":"After an adverse event, a clinician wants to express sympathy or apologize. Which statement about U.S. medical apology laws is most accurate?","key":"C","options":{"A":"Every state protects every apology, admission of fault and factual statement from evidence in exactly the same way in malpractice litigation.","B":"Apology laws prohibit clinicians from expressing sympathy after an adverse event because any compassionate statement is automatically an admission of negligence.","C":"Protections vary by jurisdiction and statement type; some laws protect expressions of sympathy, while admissions of fault may receive different or no protection.","D":"No U.S. jurisdiction addresses medical apologies or expressions of sympathy, so state law never affects disclosure communication after an adverse event."},"authority":"S","source_name":"NCSL — Medical Professional Apologies Statutes","source_url":"https://www.ncsl.org/financial-services/medical-professional-apologies-statutes","source_locator":"State-law summary and statute table show substantial variation: many jurisdictions exclude expressions of sympathy/condolence, while some extend or limit protection differently for admissions, fault or accompanying statements.","source_version":"National Conference of State Legislatures 50-state statutory summary, current page rechecked 2026-08-15; individual state law controls.","finding":"Medical apology protections are jurisdiction-specific and statement-specific. Expressions of sympathy may be protected where admissions of fault are not, so clinicians should follow applicable state law and institutional disclosure policy."},"V2-Q0875":{"stem":"After a serious adverse event, what is an appropriate role for hospital risk management within a coordinated response?","key":"C","options":{"A":"Assign individual blame before the clinical facts are established because determining fault is the only responsibility of risk management.","B":"Replace clinical quality-improvement and safety teams so only legal and financial issues are considered after an adverse event.","C":"Help coordinate event response, disclosure and risk evaluation with safety, quality, clinical and leadership teams while supporting corrective action.","D":"Prevent communication with the patient and family because disclosure after an adverse event should occur only if litigation has already begun."},"authority":"P","source_name":"AHRQ — CANDOR Response and Disclosure Framework","source_url":"https://www.ahrq.gov/patient-safety/settings/hospital/candor/modules/guide4.html","source_locator":"CANDOR framework integrates event investigation, communication/disclosure, patient/family engagement, caregiver support and resolution across organizational clinical, quality, risk and leadership functions.","source_version":"Current AHRQ CANDOR Toolkit module rechecked 2026-08-15.","finding":"Risk management participates in a coordinated adverse-event response that includes investigation, disclosure/risk evaluation and corrective action with clinical, quality and leadership functions rather than serving only as a blame-assignment office."},"V2-Q0876":{"stem":"Why does a hospital continue evaluating a practitioner's professional performance after privileges have been granted?","key":"D","options":{"A":"Once privileges are granted, subsequent performance data are irrelevant because competence is assumed permanently unless the practitioner changes employers.","B":"Ongoing evaluation exists only to verify payroll and scheduling records and is not used in decisions about clinical privileges or focused review.","C":"Recredentialing requires one universal federal renewal interval for every practitioner and facility, so performance data need not be reviewed between cycles.","D":"Ongoing professional practice evaluation supplies current performance data that inform continued privileges and whether focused review or action is needed."},"authority":"P","source_name":"The Joint Commission — Ongoing Professional Practice Evaluation (OPPE)","source_url":"https://www.jointcommission.org/en-us/knowledge-library/support-center/standards-interpretation/standards-faqs/000001322","source_locator":"OPPE FAQ explains that ongoing professional practice evaluation provides information to determine whether to continue, limit or revoke privileges and whether focused professional practice evaluation is warranted.","source_version":"Joint Commission Standards FAQ updated January 7, 2026; rechecked 2026-08-15.","finding":"Ongoing professional practice evaluation provides current competency/performance evidence for privileging decisions and can trigger focused review; a universal one-to-two-year recredentialing interval should not be substituted for the actual OPPE requirement."},"V2-Q0877":{"stem":"A unit displays an accessible dashboard of current fall, infection and hand-hygiene metrics. What is the main quality-improvement benefit?","key":"D","options":{"A":"It replaces deeper analysis because visible metrics alone identify every cause of a quality problem and specify the correct intervention.","B":"It hides performance trends from frontline staff so only analysts can decide whether improvement work is necessary.","C":"It eliminates the need to define measures or collect reliable data because dashboard visualization makes measurement methodology unnecessary.","D":"It gives teams timely visibility into performance and trends so they can monitor whether improvement efforts are producing the intended change."},"authority":"P","source_name":"AHRQ — Monitoring Progress with Quality Measures","source_url":"https://www.ahrq.gov/cahps/improvement-guide/improvement-models/progress-monitoring-measures.html","source_locator":"Quality-improvement guidance describes using measures over time to monitor progress, make performance visible and determine whether interventions are associated with improvement; dashboards are a presentation mechanism, not a substitute for analysis.","source_version":"AHRQ CAHPS Improvement Guide page last reviewed March 2026; rechecked 2026-08-15.","finding":"A quality dashboard makes defined performance measures and trends visible to the care team, supporting monitoring and feedback; it complements rather than replaces valid measurement and root-cause/improvement analysis."},"V2-Q0878":{"stem":"A client reports fatigue, pallor and shortness of breath with exertion. Which condition is a common cause of this symptom cluster?","key":"A","options":{"A":"Anemia, because reduced hemoglobin or red-cell mass can lower oxygen-carrying capacity and produce fatigue, pallor and exertional dyspnea.","B":"Isolated musculoskeletal strain, which does not typically explain pallor plus generalized fatigue and exertional shortness of breath.","C":"Normal healthy exertion, because persistent pallor and unusual fatigue should be assumed normal whenever symptoms occur during activity.","D":"Uncomplicated dermatitis, which may change the skin locally but does not explain reduced exercise tolerance and systemic pallor."},"authority":"P","source_name":"NHLBI — Anemia","source_url":"https://www.nhlbi.nih.gov/health/anemia/vitamin-b12-deficiency-anemia","source_locator":"NHLBI anemia symptom discussion includes tiredness/weakness, pale skin and shortness of breath among manifestations related to inadequate healthy red blood cells/oxygen delivery.","source_version":"Current NIH/NHLBI anemia health information rechecked 2026-08-15.","finding":"Fatigue, pallor and exertional dyspnea are common manifestations of anemia, although they are nonspecific and require evaluation such as CBC and assessment of the underlying cause."},"V2-Q0879":{"stem":"A client with polycythemia vera asks why the disorder increases the risk of thrombosis. Which explanation is most accurate?","key":"D","options":{"A":"The disorder consistently causes too few red blood cells, so thrombosis results primarily from severe anemia and reduced blood viscosity.","B":"Polycythemia vera affects only skin color and does not alter blood-cell mass or the risk of arterial or venous thrombotic events.","C":"The principal complication is always spontaneous hemorrhage from isolated thrombocytopenia, while thrombotic events are not associated with the disease.","D":"Increased blood-cell mass and disease-related blood abnormalities contribute to arterial and venous thrombosis, a major complication of polycythemia vera."},"authority":"P","source_name":"National Cancer Institute — Chronic Myeloproliferative Neoplasms Treatment","source_url":"https://www.cancer.gov/types/myeloproliferative/patient/chronic-treatment-pdq","source_locator":"Polycythemia vera section describes increased red-cell production/hyperviscosity and clinically important thrombotic complications; therapy aims in part to reduce thrombosis risk.","source_version":"Current NCI PDQ patient treatment summary rechecked 2026-08-15.","finding":"Polycythemia vera increases the risk of arterial and venous thrombosis through increased cell mass and disease-related hematologic abnormalities; thrombosis is a major driver of morbidity."},"V2-Q0880":{"stem":"A client has fatigue, easy bruising, recurrent infections, bone pain and abnormal blood counts. Which disorder warrants prompt hematologic evaluation?","key":"C","options":{"A":"A routine viral upper-respiratory infection, which does not adequately explain persistent bruising, bone pain and multilineage blood-count abnormalities.","B":"An isolated orthopedic injury, which may cause focal bone pain but does not explain recurrent infections, bruising and abnormal hematologic findings.","C":"Leukemia, because marrow involvement can disrupt normal blood-cell production and cause fatigue, infection, bleeding/bruising and bone discomfort.","D":"Uncomplicated iron deficiency alone, which may cause anemia but does not by itself explain the full pattern of infections, bruising and abnormal white-cell findings."},"authority":"P","source_name":"National Cancer Institute/SEER — Leukemia Evaluation","source_url":"https://training.seer.cancer.gov/hematopoietic1/evaluation/physical-exam.html","source_locator":"Leukemia clinical evaluation material notes fatigue/weakness from anemia, infection, easy bruising/bleeding from marrow dysfunction and bone/joint pain as possible findings prompting hematologic evaluation.","source_version":"Official NCI SEER Training Modules current content rechecked 2026-08-15.","finding":"The combination of fatigue, bruising/bleeding, recurrent infection, bone pain and abnormal blood counts is concerning for leukemia because marrow disease disrupts normal hematopoiesis; diagnosis requires formal hematologic testing."},"V2-Q0881":{"stem":"A client has persistent painless lymphadenopathy with unexplained fever, drenching night sweats and weight loss. Which condition should be evaluated?","key":"B","options":{"A":"Simple allergic rhinitis, which does not typically explain persistent painless lymph-node enlargement accompanied by constitutional B symptoms.","B":"Lymphoma, because persistent lymphadenopathy with fever, drenching night sweats and unexplained weight loss is a classic concerning symptom pattern.","C":"Uncomplicated short-lived viral illness, which should not be assumed when lymphadenopathy persists together with significant unexplained systemic symptoms.","D":"Localized dermatitis, which may cause skin symptoms but does not account for persistent generalized lymphadenopathy and constitutional B symptoms."},"authority":"P","source_name":"National Cancer Institute — Adult Hodgkin Lymphoma Treatment (PDQ)","source_url":"https://www.cancer.gov/types/lymphoma/patient/adult-hodgkin-treatment-pdq","source_locator":"Signs/symptoms section: painless swollen lymph nodes plus fever, drenching night sweats and unexplained weight loss are classic Hodgkin lymphoma findings; diagnosis requires tissue evaluation/biopsy.","source_version":"Current NCI PDQ adult Hodgkin lymphoma summary rechecked 2026-08-15.","finding":"Persistent painless lymphadenopathy with unexplained fever, drenching night sweats and weight loss is concerning for lymphoma and warrants diagnostic evaluation, including tissue diagnosis when indicated."}}''')


def dump(v):
    return json.dumps(v, ensure_ascii=False, sort_keys=True, separators=(",", ":"))


def metrics(options, key):
    lengths = {k: len(str(v).strip()) for k, v in options.items()}
    vals = list(lengths.values())
    ratio = max(vals) / max(min(vals), 1)
    dmean = sum(lengths[k] for k in "ABCD" if k != key) / 3
    dev = abs(lengths[key] - dmean) / max(dmean, 1)
    unique = ((lengths[key] == min(vals) and vals.count(min(vals)) == 1) or
              (lengths[key] == max(vals) and vals.count(max(vals)) == 1))
    return lengths, ratio, dev, unique


def main():
    pending = json.loads(PENDING.read_text(encoding="utf-8"))
    if pending.get("range") != [832, 881] or pending.get("count") != 50:
        raise SystemExit(f"Batch006 pending scope mismatch: {pending.get('range')} count={pending.get('count')}")
    if [q.get("question_uid") for q in pending.get("questions", [])] != IDS:
        raise SystemExit("Batch006 pending IDs mismatch")
    if set(MANUAL) != set(IDS) or len(MANUAL) != 50:
        raise SystemExit("Batch006 manual semantic package must contain exactly Q0832-Q0881")
    if {u for u,x in MANUAL.items() if x["authority"] == "S"} != SECONDARY:
        raise SystemExit("Batch006 secondary exception set mismatch")

    con = sqlite3.connect(DB)
    con.row_factory = sqlite3.Row
    rows = {r["question_uid"]: r for r in con.execute(
        "SELECT question_uid,source_id,category_id,client_need,difficulty,correct_answer_json FROM questions "
        "WHERE question_uid BETWEEN 'V2-Q0832' AND 'V2-Q0881' ORDER BY question_uid"
    )}
    con.close()
    if set(rows) != set(IDS):
        raise SystemExit("Batch006 DB scope mismatch")

    evidence_items = []
    overrides = []
    max_ratio = 0.0
    max_dev = 0.0
    for uid in IDS:
        m = MANUAL[uid]
        r = rows[uid]
        db_key = json.loads(r["correct_answer_json"])["correct_option"]
        if db_key != m["key"]:
            raise SystemExit(f"{uid}: verified key mismatch DB={db_key} manual={m['key']}")
        options = m["options"]
        if set(options) != set("ABCD") or any(not str(v).strip() for v in options.values()):
            raise SystemExit(f"{uid}: invalid four-option schema")
        if len({str(v).strip().casefold() for v in options.values()}) != 4:
            raise SystemExit(f"{uid}: duplicate option")
        lengths, ratio, dev, unique = metrics(options, m["key"])
        if ratio > 1.15 + 1e-12 or dev > 0.10 + 1e-12 or unique:
            raise SystemExit(f"{uid}: option QC failed ratio={ratio:.4f} dev={dev:.4f} unique={unique}")
        if not m["source_url"].startswith("https://") or len(m["source_locator"]) < 45 or len(m["source_version"]) < 20:
            raise SystemExit(f"{uid}: source evidence incomplete")
        max_ratio = max(max_ratio, ratio)
        max_dev = max(max_dev, dev)
        qc = {
            "characters": lengths,
            "max_min_ratio": round(ratio, 4),
            "correct_option": m["key"],
            "correct_deviation_from_distractor_mean": round(dev, 4),
            "correct_unique_length_extreme": False,
            "artificial_padding": False,
            "semantic_option_rewrite": True,
        }
        evidence_items.append({
            "id": uid,
            "key": m["key"],
            "category_id": r["category_id"],
            "client_need": r["client_need"],
            "difficulty": r["difficulty"],
            "authority": m["authority"],
            "source_url": m["source_url"],
            "source_locator": m["source_locator"],
            "source_version": m["source_version"],
            "finding": m["finding"],
            "criteria": 11,
            "second_pass": "PASS",
            "final": "FINAL_QA_PASS",
            "reviewed_at": "2026-08-15",
            "option_qc": qc,
        })
        flags = [
            "RULE1_BATCH006_REAL_REAUDIT",
            "SOURCE_LOCATOR_VERSION_CURRENTNESS_VERIFIED",
            "SECOND_PASS_QA_PASS",
            "STRICT_OPTION_LENGTH_ANTI_CUE_QC_PASS",
            "ALL_OPTIONS_SEMANTIC_REWRITE",
        ]
        if uid in SUBSTANTIVE:
            flags.append("SUBSTANTIVE_CORRECTION")
        if uid in SECONDARY:
            flags.append("DOCUMENTED_SECONDARY_SOURCE_EXCEPTION")
        source_detail = f"{m['source_locator']} {m['source_version']} Reviewed 2026-08-15."
        overrides.append({
            "question_uid": uid,
            "source_id": r["source_id"],
            "stem": m["stem"],
            "item_data_json": dump({"options": options}),
            "correct_answer_json": dump({"correct_option": m["key"]}),
            "rationale": m["finding"],
            "source_name": m["source_name"],
            "source_detail": source_detail,
            "source_url": m["source_url"],
            "clinical_qa_status": "SOURCE_VERIFIED_2026_RULE1_BATCH006",
            "editorial_priority": "PRODUCTION_CANDIDATE",
            "editorial_flags_json": dump(flags),
            "qc": {
                "question_uid": uid,
                "lengths_json": dump(lengths),
                "min_chars": min(lengths.values()),
                "max_chars": max(lengths.values()),
                "max_min_ratio": round(ratio, 4),
                "correct_option": m["key"],
                "correct_length_rank": 1 + sum(1 for n in lengths.values() if n < lengths[m["key"]]),
                "correct_is_extreme": 0,
                "qc_status": "PASS",
                "qc_note": "Rule 1 Batch 006 semantic option/cue QC: all four options manually rewritten; max/min <=1.15; correct-option deviation <=10%; correct option is not a unique length extreme; no artificial padding.",
            },
        })

    evidence_doc = {
        "standard": "RULE_1_FINAL_10_OF_10_REAL_REAUDIT",
        "batch": "Q0832-Q0881",
        "legacy_status_evidence": False,
        "criteria_names": CRITERIA,
        "secondary_source_exceptions": sorted(SECONDARY),
        "substantive_corrections": sorted(SUBSTANTIVE),
        "all_options_semantically_rewritten": True,
        "items": evidence_items,
    }
    override_doc = {"version": "2026-08-15-rule1-batch006-real-reaudit", "questions": overrides}
    EVIDENCE.write_text(json.dumps(evidence_doc, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    OVERRIDE.write_text(json.dumps(override_doc, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"BATCH006_ARTIFACTS_BUILT items=50/50 criteria11=50/50 corrections={len(SUBSTANTIVE)}/12 secondary={len(SECONDARY)}/7 option_qc=50/50 all_options_semantic=50/50 max_ratio={max_ratio:.4f} max_dev={max_dev:.4f}")


if __name__ == "__main__":
    main()
